        byte[] raw=NextflowFiles.bytes(request.runtime(),67108864);var manifest=read(request.runtime(),67108864);var pin=new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));require(pin.equals(NextflowFiles.pin(request.runtime(),67108864,()->{})),"Runtime receipt changed during capture");
